function update(dt){if(keys.ArrowLeft||keys.a||keys.A)paddle.x-=paddle.speed*dt;if(keys.ArrowRight||keys.d||keys.D)paddle.x+=paddle.speed*dt;paddle.x=Math.max(8,Math.min(W-paddle.w-8,paddle.x));if(ball.stuck){ball.x=paddle.x+paddle.w/2;ball.y=paddle.y-18;return}ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;if(ball.x<ball.r+5){ball.x=ball.r+5;ball.vx=Math.abs(ball.vx)}if(ball.x>W-ball.r-5){ball.x=W-ball.r-5;ball.vx=-Math.abs(ball.vx)}if(ball.y<ball.r+5){ball.y=ball.r+5;ball.vy=Math.abs(ball.vy)}if(ball.y>H+ball.r){lives--;updateHud();if(lives<=0){end('"'Гру завершено','Цеглинки перемогли цього разу. Спробуй ще"'!'"','Спробувати знову');return}resetBall();return}
